/* Official program discovery stays separate from degree requirement coverage. */
let programDirectoryQuery='',programDirectorySchool='',programDirectoryPage=0;
function programDirectory(uwOnly=false){return journeyPage(2,uwOnly?'Explore UW’s undergraduate majors.':'Every direction deserves a place.',`<p class="journey-lede">Choose a primary program and a backup. Listings show availability; degree requirements need their own official checklist.</p>${(state.degreeGoals||[]).filter(g=>g.role==='primary'||g.role==='backup').length?`<div class="degree-summary"><p>${(state.degreeGoals||[]).filter(g=>g.role==='primary'||g.role==='backup').map(g=>`<strong>${esc(g.role)}:</strong> ${esc(g.name)}`).join(' · ')}</p><a class="journey-secondary" href="#degrees">Open checklists →</a></div>`:''}${uwCatalogCoverage()}<div class="journey-actions"><a class="btn" href="#college-catalogs">Read Cascadia’s full degree requirements →</a><a class="btn" href="#transfer-guides">Find transfer equivalents →</a></div><label>Search programs<input id="program-search" type="search" value="${esc(programDirectoryQuery)}" placeholder="Try Informatics, engineering, psychology…"></label><label>College<select id="program-school">${uwOnly?'':'<option value="">All listed colleges</option>'}<option value="__uw_all__" ${programDirectorySchool==='__uw_all__'?'selected':''}>All UW campuses</option>${ProgramCatalog.institutions.filter(s=>!uwOnly||/^UW /.test(s.name)).map(s=>`<option ${programDirectorySchool===s.name?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><div id="program-list"></div><details class="journey-advanced"><summary>Program missing? Add its exact official name</summary><form id="custom-program"><label>Program name<input name="title" maxlength="150" required></label><label>College<select name="institution">${ProgramCatalog.institutions.map(s=>`<option>${esc(s.name)}</option>`).join('')}</select></label><label>Official program URL<input type="url" name="url" required placeholder="https://"></label><label>Role<select name="role"><option value="primary">Primary</option><option value="backup">Backup preparation</option></select></label><button class="btn">Use this program</button></form><p>Custom entries are student-entered and need college verification.</p></details><p class="quiet-note">Directory snapshots checked ${ProgramCatalog.checked}. Coverage varies: WSU now includes all reviewed undergraduate General Catalog major/option schedules; confirm offering campus. Seattle and Cascadia listings include transfer focus areas and non-degree study. Program listings are broader than verified requirement checklists. A listed program is not a verified curriculum or transfer guarantee.</p><a class="journey-secondary" href="#degrees">Open connected degree plan →</a>`,'results')}
function selectProgram(p,role){state.degreeGoals||=[];const other=state.degreeGoals.find(g=>g.role===(role==='primary'?'backup':'primary'));if(other&&other.institution===p.institution&&other.name===p.title)return toast('Choose a different program for your backup.');let goal=state.degreeGoals.find(g=>g.role===role);if(goal?.requirements.length)return toast('This role already has an entered checklist. Change its role in the connected plan before replacing it.');if(!goal&&state.degreeGoals.length>=6)return toast('Use up to six goals.');const next={id:goal?.id||degreeIds(),name:p.title,institution:p.institution,kind:role==='backup'?'Backup admission preparation':'Program goal',role,source:p.url,programId:p.id||'',credential:p.credential||'',parentMajor:p.parentMajor||'',campus:p.campus||'',sharing:'review',advisorConfirmed:false,requirements:[]};if(goal)state.degreeGoals[state.degreeGoals.indexOf(goal)]=next;else state.degreeGoals.push(next);state.profile={...state.profile,[role==='backup'?'backupMajor':'primaryProgram']:p.title};if(role==='primary'){const target=({'UW Seattle':'University of Washington Seattle','UW Bothell':'University of Washington Bothell','UW Tacoma':'University of Washington Tacoma'}[p.institution]||p.institution),calendar=ProductCore.institutions.find(c=>c.name===target)?.calendar||state.profile.calendar||'Quarter';state.profile={...state.profile,major:p.title,target,primaryProgramId:p.id||'',calendar,startTerm:calendar==='Semester'?'Fall':state.profile.startTerm||'Winter'}}save();toast((role==='backup'?'Backup':'Primary')+' saved. Add its official requirements in the connected plan.');render()}
function bindPrograms(){const list=document.querySelector('#program-list');if(list){let page=programDirectoryPage;const update=()=>{const q=document.querySelector('#program-search').value.toLowerCase(),school=document.querySelector('#program-school').value;const rows=ProgramCatalog.programs.filter(p=>(!school||school==='__uw_all__'&&/^UW /.test(p.institution)||p.institution===school)&&[p.title,p.credential,p.parentMajor,p.campus].join(' ').toLowerCase().includes(q));page=Math.min(page,Math.max(0,Math.ceil(rows.length/24)-1));programDirectoryPage=page;programDirectoryQuery=q;programDirectorySchool=school;const visible=rows.slice(page*24,page*24+24);list.innerHTML=`<p role="status">${rows.length} matching directory entries · showing ${rows.length?page*24+1:0}–${Math.min(rows.length,page*24+24)}</p>${ProgramCatalog.institutions.filter(s=>!school||school==='__uw_all__'&&/^UW /.test(s.name)||school===s.name).map(s=>`<p><a class="journey-secondary" href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.name)} official directory ↗</a> · ${esc(s.note||(s.coverage==='snapshot'?'Listing snapshot; requirements coverage varies':'Directory coverage incomplete'))}</p>`).join('')}<div class="degree-goals">${visible.map(p=>`<article class="degree-goal"><span class="eyebrow">${esc(p.institution)}</span><h3>${esc(p.title)}</h3><p>${esc(p.credential||p.kind)}</p>${p.parentMajor?`<p class="quiet-note">Major family: ${esc(p.parentMajor)} · ${esc(p.campus)}</p>`:''}${p.institution==='UW Seattle'&&p.title==='Informatics'?'<p>Admission preparation differs for current UW Seattle students and transfer applicants. This listing does not load the full degree checklist.</p><a class="journey-secondary" href="https://ischool.uw.edu/programs/informatics/admissions/prerequisites" target="_blank" rel="noopener">Official Informatics prerequisites ↗</a>':''}<a class="journey-secondary" href="${esc(p.url)}" target="_blank" rel="noopener">Official program ↗</a>${p.id.startsWith('wsu-catalog-')?`<button class="btn" data-wsu-requirements="${esc(p.id)}">Read published requirements & course sequence</button>`:''}${p.id.includes('-credential-')?`<button class="btn" data-uw-requirements="${esc(p.id)}">Read full published requirements</button>`:''}<button class="journey-secondary" data-read-program-source="${esc(p.id)}">Read current official program page</button><div class="actions"><button class="btn" data-program="${esc(p.id)}" data-role="primary">Primary</button><button class="btn" data-program="${esc(p.id)}" data-role="backup">Backup</button></div></article>`).join('')}</div>${rows.length>24?`<div class="actions"><button class="btn" id="program-previous" ${page===0?'disabled':''}>← Previous programs</button><span>Page ${page+1} of ${Math.ceil(rows.length/24)}</span><button class="btn" id="program-next" ${(page+1)*24>=rows.length?'disabled':''}>More programs →</button></div>`:''}`;list.querySelector('#program-previous')?.addEventListener('click',()=>{page--;update()});list.querySelector('#program-next')?.addEventListener('click',()=>{page++;update()});bindResearch();bindUWCatalog();bindCatalogPlanner();list.querySelectorAll('[data-program]').forEach(b=>b.onclick=()=>selectProgram(ProgramCatalog.programs.find(p=>p.id===b.dataset.program),b.dataset.role))};document.querySelector('#program-search').oninput=()=>{page=0;update()};document.querySelector('#program-school').onchange=()=>{page=0;update()};update();document.querySelector('#custom-program').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));if(!ProductCore.safeURL(f.url))return toast('Use an HTTPS official program URL.');selectProgram(f,f.role)}}}
function installPrograms(){const oldBind=bind;bind=function(){oldBind();bindPrograms()};const oldExplore=explore;explore=function(){return oldExplore()+`<div class="degree-summary"><a class="journey-secondary" href="#programs">Browse all loaded official programs and choose a backup →</a></div>`};const oldProfile=profile;profile=function(){return oldProfile()+`<div class="degree-summary"><a class="journey-secondary" href="#programs">Choose an exact program or backup major →</a></div>`}}
